// =====================================================
// รวมคอมเมนท์จัดซื้อ (หาเคสข้ามเดือน) — v2  (8 ต.ค.69)
// แทนโหนด "Code in JavaScript2" + "Merge" + "Merge Node" ชุดเดิม
//
// รับผลจาก "อ่านเคส 2 เดือน (ชีต)" = คอลัมน์ C–Q ของแท็บเดือนนี้ [0] + เดือนก่อน [1]
// หาแถวที่ Code ตรง → เดือนนี้ก่อน ไม่เจอค่อยเดือนก่อน (วัดจริง: คอมเมนท์ต้นเดือนพูดถึงเคสเดือนก่อนได้ ห่างถึง 11 วัน)
// เจอหลายแถว = เอาแถวล่างสุด (ล่าสุด) · ไม่เจอ = ข้าม ไม่เขียนมั่ว
// คืน { tab, row, comment } ให้ "อัปเดตคอมเมนท์ (ชีต)" เขียนช่อง Q ของแถวนั้น
// =====================================================

// ข้อมูลคอมเมนท์มาจากโหนด Build Sheet Row (ลองหลายชื่อเผื่อเปลี่ยนชื่อโหนด)
const NAMES = ["Build Sheet Row (Trade-in)", "Build Sheet Row v22", "Build Sheet Row v21"];
let b = null;
for (const n of NAMES) {
  try { b = $(n).first().json; } catch (e) { b = null; }
  if (b) break;
}
if (!b) {
  throw new Error("หาโหนด Build Sheet Row ไม่เจอ — ชื่อต้องเป็นหนึ่งใน: " + NAMES.join(" / "));
}
if (b._mode !== "purchase_comment") {
  throw new Error("ต่อสายผิด: โหนดนี้ต้องรับทาง false ของ If1 (คอมเมนท์จัดซื้อ) เท่านั้น");
}
if (!b._tab) {
  throw new Error("Build Sheet Row ยังเป็นรุ่นเก่า (ไม่มี _tab) — วางโค้ด v22 จาก deploy/n8n_tradein_build_row.js");
}

const norm = (s) => String(s || "").replace(/\s+/g, "").toUpperCase();
const target = norm(b.code);
const newComment = String(b.comment || "").trim();
if (!target || !newComment) {
  console.log("ไม่มีรหัสเคสหรือข้อความคอมเมนท์ — ข้าม");
  return [];
}

const ranges = ($input.first().json || {}).valueRanges || [];
const tabs = [b._tab, b._tabPrev];
let found = null;
for (let t = 0; t < ranges.length && !found; t++) {
  const rows = ranges[t].values || [];
  for (let i = rows.length - 1; i >= 0; i--) {        // ล่างสุดก่อน = แถวล่าสุด
    if (norm(rows[i][0]) === target) {                // [0] = คอลัมน์ C (Code)
      found = { tab: tabs[t], row: i + 3, old: String(rows[i][14] || "").trim() };  // [14] = Q
      break;
    }
  }
}

if (!found) {
  console.log("ไม่เจอเคส", b.code, "ในแท็บ", tabs.join(" / "), "— ข้าม");
  return [];
}

let merged = newComment;
if (found.old) {
  if (found.old === newComment || found.old.includes(newComment)) merged = found.old;
  else merged = found.old + " / " + newComment;
}
if (merged === found.old) {
  console.log("คอมเมนท์นี้มีอยู่แล้ว — ไม่เขียนซ้ำ");
  return [];
}

console.log("เขียนคอมเมนท์", b.code, "→", found.tab, "แถว", found.row);
return [{ json: { tab: found.tab, row: found.row, code: b.code, comment: merged } }];
